fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    // If maxsplit == 0, no splitting, just wrap each original string in a vector.
    if maxsplit == 0 {
        return a.into_iter().map(|s| vec![s]).collect();
    }

    // maxsplit > 0: perform right splits with rsplitn(maxsplit + 1)
    a.into_iter()
        .map(|s| {
            s.rsplitn((maxsplit as usize) + 1, &sep)
                .map(|part| part.to_string())
                .collect()
        })
        .collect()
}